const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(helmet.permittedCrossDomainPolicies()); // Prevent CDP attacks
app.disable('x-powered-by'); // Hide server information

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// Input validation and sanitization
app.use(express.json({
  limit: '10kb' // Limit request body size
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Rate limiting to prevent abuse
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});
app.use('/api/', limiter); // Apply rate limiting to API routes

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${new Date().toISOString()} ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// Input validation helper
const validateUserId = (id) => {
  const userId = parseInt(id, 10);
  return {
    isValid: !isNaN(userId) && userId > 0,
    value: userId
  };
};

// Health check endpoint
app.get('/health', (req, res) => {
  // Validate query parameters if present
  if (Object.keys(req.query).length > 0) {
    const validParams = ['format']; // Only allow specific query parameters
    const invalidParams = Object.keys(req.query).filter(param => !validParams.includes(param));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Invalid query parameters: ${invalidParams.join(', ')}`,
        code: 'INVALID_PARAMETERS'
      });
    }
  }

  const healthData = {
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: process.env.npm_package_version || '1.0.0'
  };

  // Handle format parameter
  if (req.query.format === 'detailed') {
    healthData.host = req.hostname;
    healthData.ip = req.ip;
  }

  res.json(healthData);
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page, limit, sort } = req.query;

    // Pagination validation
    let validatedPage = 1;
    let validatedLimit = 10;

    if (page !== undefined) {
      const pageValidation = validateUserId(page);
      if (!pageValidation.isValid || pageValidation.value > 1000) {
        return res.status(400).json({
          error: 'Invalid page number. Must be a positive integer less than 1000',
          code: 'INVALID_PAGE'
        });
      }
      validatedPage = pageValidation.value;
    }

    if (limit !== undefined) {
      const limitValidation = validateUserId(limit);
      if (!limitValidation.isValid || limitValidation.value > 100) {
        return res.status(400).json({
          error: 'Invalid limit. Must be a positive integer less than 100',
          code: 'INVALID_LIMIT'
        });
      }
      validatedLimit = limitValidation.value;
    }

    // Sort validation
    const validSortFields = ['name', 'email', 'id'];
    const validSortDirections = ['asc', 'desc'];
    let validatedSort = null;

    if (sort !== undefined) {
      const sortParts = sort.split('_');
      if (sortParts.length !== 2) {
        return res.status(400).json({
          error: 'Invalid sort format. Use field_direction (e.g., name_asc)',
          code: 'INVALID_SORT_FORMAT'
        });
      }

      const [field, direction] = sortParts;
      if (!validSortFields.includes(field)) {
        return res.status(400).json({
          error: `Invalid sort field. Must be one of: ${validSortFields.join(', ')}`,
          code: 'INVALID_SORT_FIELD'
        });
      }

      if (!validSortDirections.includes(direction)) {
        return res.status(400).json({
          error: `Invalid sort direction. Must be one of: ${validSortDirections.join(', ')}`,
          code: 'INVALID_SORT_DIRECTION'
        });
      }

      validatedSort = { field, direction };
    }

    // Mock user data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply sorting
    let sortedUsers = [...mockUsers];
    if (validatedSort) {
      sortedUsers.sort((a, b) => {
        const aValue = a[validatedSort.field].toLowerCase();
        const bValue = b[validatedSort.field].toLowerCase();

        if (aValue < bValue) return validatedSort.direction === 'asc' ? -1 : 1;
        if (aValue > bValue) return validatedSort.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }

    // Apply pagination
    const startIndex = (validatedPage - 1) * validatedLimit;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + validatedLimit);

    // Prepare response
    const response = {
      data: paginatedUsers,
      page: validatedPage,
      limit: validatedLimit,
      total: mockUsers.length,
      totalPages: Math.ceil(mockUsers.length / validatedLimit),
      timestamp: new Date().toISOString()
    };

    res.json(response);
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle different types of errors
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: error.message,
      code: 'VALIDATION_ERROR'
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized access',
      code: 'UNAUTHORIZED'
    });
  }

  // Default to 500 for unhandled errors
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_ERROR'
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;
module.exports.server = server;

