const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware for users route
const validateUsersQuery = [
  (req, res, next) => {
    // Basic validation - only allow specific query parameters
    const allowedParams = ['limit', 'page', 'search'];
    const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Invalid query parameters: ${invalidParams.join(', ')}`
      });
    }

    // Validate limit parameter
    if (req.query.limit !== undefined) {
      const limit = parseInt(req.query.limit);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Limit must be a number between 1 and 100'
        });
      }
    }

    // Validate page parameter
    if (req.query.page !== undefined) {
      const page = parseInt(req.query.page);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({
          error: 'Page must be a positive number'
        });
      }
    }

    next();
  }
];

app.get('/health', (req, res) => {
  // Explicitly reject any query parameters on health check
  if (Object.keys(req.query).length > 0) {
    return res.status(400).json({
      error: 'Health check endpoint does not accept query parameters'
    });
  }

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', validateUsersQuery, (req, res) => {
  try {
    // Sample data - in a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple search functionality if search query is provided
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      const filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    console.error('Error processing /users request:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Don't expose sensitive error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: isProduction ? 'Internal server error' : error.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

