/**
 * Centralized error handling middleware
 * Handles all errors in the application
 */

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

const errorHandler = (err, req, res, next) => {
  // Log error details (in production, use a proper logging service)
  console.error('Error:', err);

  // Set default error values
  let { statusCode = 500, message = 'Internal Server Error' } = err;

  // Handle validation errors from express-validator
  if (err.name === 'ValidationError') {
    statusCode = 400;
    message = err.message;
  }

  // Handle CastError (invalid MongoDB ID, if used later)
  if (err.name === 'CastError') {
    statusCode = 400;
    message = `Invalid ${err.path}: ${err.value}`;
  }

  // Handle duplicate field values (if using MongoDB)
  if (err.code === 11000) {
    const field = Object.keys(err.keyValue);
    message = `Duplicate field value: ${field}. Please use another value!`;
    statusCode = 400;
  }

  // Send response
  res.status(statusCode).json({
    status: 'error',
    statusCode,
    message
  });
};

module.exports = {
  errorHandler,
  AppError
};

/**
 * Validation middleware for user-related routes
 */
const { query, param, validationResult } = require('express-validator');

// Validate query parameters for /users endpoint
