const express = require('express');
const path = require('path');

const app = express();

// Security headers middleware
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size
  if (req.method === 'POST' || req.method === 'PUT') {
    const contentLength = req.headers['content-length'];
    if (contentLength && parseInt(contentLength) > 10240) { // 10kb limit
      return res.status(413).json({
        status: 'error',
        message: 'Payload too large'
      });
    }
  }

  next();
});

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);

  const originalSend = res.send;
  res.send = function(body) {
    const responseTime = Date.now() - startTime;
    console.log(`Response time: ${responseTime}ms - Status: ${res.statusCode}`);
    return originalSend.call(this, body);
  };

  next();
});

// Body parsing with size limit
app.use(express.json({ 
  limit: '10kb',
  verify: (req, res, buf) => {
    try {
      JSON.parse(buf);
    } catch (e) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid JSON format'
      });
    }
  }
}));

// Input validation utility functions
const validateEmail = (email) => {
  const re = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
  return re.test(String(email).toLowerCase());
};

// Prevent prototype pollution
const sanitizeUserInput = (obj) => {
  if (obj && obj.constructor === Object) {
    Object.keys(obj).forEach(key => {
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
        delete obj[key];
      }
    });
  }
  return obj;
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Validate query parameters
    if (Object.keys(req.query).length > 0) {
      const validParams = ['verbose'];
      const invalidParams = Object.keys(req.query).filter(param => 
        !validParams.includes(param)
      );

      if (invalidParams.length > 0) {
        return res.status(400).json({
          status: 'error',
          message: `Invalid query parameters: ${invalidParams.join(', ')}`
        });
      }
    }

    const healthData = { 
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    // Add verbose data if requested
    if (req.query.verbose === 'true') {
      healthData.service = 'user-service';
      healthData.version = '1.0.0';
    }

    res.status(200).json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error'
    });
  }
});

