app.get('/users', (req, res) => {
  try {
    // Validate query parameters for users endpoint
    const validParams = ['limit', 'offset', 'format'];
    const requestedParams = Object.keys(req.query);

    // Check for invalid parameters
    const invalidParams = requestedParams.filter(param => 
      !validParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: `Invalid query parameters: ${invalidParams.join(', ')}'
      });
    }

    // Validate and sanitize parameters
    let limit = 10;
    if (req.query.limit) {
      const limitNum = parseInt(req.query.limit);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
