require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('rate-limiter-flexible');
const winston = require('winston');
const { body, validationResult, query } = require('express-validator');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    //
    // - Write to all logs with level `info` and below to `combined.log`
    // - Write all logs error (and below) to `error.log`.
    //
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

// If we're not in production then log to the console as well
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = new rateLimit.RateLimiterMemory({
  points: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  duration: parseInt(process.env.RATE_LIMIT_WINDOW) || 15,
});

app.use((req, res, next) => {
  limiter.consume(req.ip)
    .then(() => {
      next();
    })
    .catch(() => {
      logger.warn(`Rate limit exceeded by IP: ${req.ip}`, { ip: req.ip });
      res.status(429).json({ error: 'Rate limit exceeded' });
    });
});

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware for users endpoint
const validateUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),

  query('sort')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Sort must be one of: name, email, id'),

  query('order')
    .optional()
    .isIn(['asc', 'desc'])
    .withMessage('Order must be either asc or desc'),
];

// Health check endpoint
app.get('/health', [
  // Add validation for health endpoint query parameters if needed
  query('detailed').optional().isBoolean().toBoolean()
], (req, res) => {
  // Validate request
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error in health endpoint', { 
      errors: errors.array(), 
      ip: req.ip, 
      url: req.url 
    });
    return res.status(400).json({ 
      error: 'Invalid request parameters',
      details: errors.array() 
    });
  }

  const healthData = {
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  };

  // Add detailed info if requested
  if (req.query.detailed) {
    healthData.details = {
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };
  }

  logger.info('Health check endpoint accessed', { ip: req.ip });
  res.json(healthData);
});

// Users endpoint with validation
app.get('/users', validateUsersQuery, (req, res) => {
  // Validate request
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error in users endpoint', { 
      errors: errors.array(), 
      ip: req.ip, 
      url: req.url 
    });
    return res.status(400).json({ 
      error: 'Invalid request parameters',
      details: errors.array() 
    });
  }

  // Mock user data
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Process query parameters for filtering/sorting
  const limit = req.query.limit || 10;
  const page = req.query.page || 1;
  const sort = req.query.sort || 'id';
  const order = req.query.order || 'asc';

  // Sort users
  users.sort((a, b) => {
    if (order === 'asc') {
      return a[sort] > b[sort] ? 1 : -1;
    } else {
      return a[sort] < b[sort] ? 1 : -1;
    }
  });

  // Apply pagination
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const paginatedUsers = users.slice(startIndex, endIndex);

  logger.info('Users endpoint accessed', { 
    ip: req.ip, 
    query: req.query 
  });

  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      page: page,
      pages: Math.ceil(users.length / limit),
      limit: limit
    }
  });
});

// Catch 404 errors
app.use('*', (req, res) => {
  logger.warn('404 endpoint not found', { 
    method: req.method, 
    url: req.url, 
    ip: req.ip 
  });

  res.status(404).json({
    error: 'Endpoint not found'
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak sensitive error details in production
  const errorResponse = {
    error: 'Internal server error'
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(500).json(errorResponse);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught exception', {
    error: err.message,
    stack: err.stack
  });

  // Allow server to exit gracefully
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  logger.error('Unhandled promise rejection', {
    error: err.message,
    stack: err.stack
  });

  // Allow server to exit gracefully
  process.exit(1);
});

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = { app, server, logger };

