const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : true // Allow all in development
}));

// Input sanitization and validation
app.use(express.json({
  limit: '10kb' // Limit request size
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const allowedParams = ['format', 'detailed'];
    const invalidParams = Object.keys(req.query).filter(param => 
      !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Invalid query parameters: ${invalidParams.join(', ')}`
      });
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    };

    // Optional detailed response
    if (req.query.detailed === 'true') {
      healthData.services = {
        database: 'connected',
        cache: 'connected'
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with improved security
app.get('/users', (req, res) => {
  try {
    // Log request (without sensitive info)
    console.log(`GET /users from IP: ${req.ip}`);

    // Input validation
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;

    // Validate and sanitize inputs
    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Page must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Limit must be a positive integer between 1 and 100'
      });
    }

    // Mock users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simulate pagination
    const totalPages = Math.ceil(users.length / limit);

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        totalPages,
        total: users.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);

  // Hide error details in production
  const errorResponse = {
    error: 'Internal server error'
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(500).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

